pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }
    function testRegression_property() public {
        Token token = new Token();
        address alice = address(0x1234);
        address[] memory tos = new address[](1);
        tos[0] = alice;
        c.transfer(alice, address(token), tos, 100);
        assertTrue(token.lastCaller() == alice, "lastCaller should be alice in correct version");
    }
}

contract Token {
    address public lastCaller;
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        lastCaller = from;
        return true;
    }
}
